const groups = [
  {
    ending: 'Forms in -να',
    entries: [
      ['μέλαινα', 'μέλανος', 'Antepenult acute', 'μέ', 'μέλανος is the masculine genitive. With short final -α, μέλαινα has its acute on the third syllable from the end.'],
      ['δράκαινα', 'δράκων', 'Antepenult acute', 'δρά', 'Herodian pairs δράκων with δράκαινα among the forms with short final -α.'],
      ['Μελαιναί', '', 'Final acute', 'αί', 'Herodian gives a final acute to the Arcadian city name Μελαιναί, citing Pausanias (8.26.8). He also records a Lycian city of that name, citing Alexander’s Lyciaca.']
    ]
  },
  {
    ending: 'Forms in -ρα',
    entries: [
      ['σώτειρα', 'σωτήρ', 'Antepenult acute', 'σώ', 'Herodian pairs σωτήρ with σώτειρα. The penult of σώτειρα contains ει, and the acute is on the preceding syllable.'],
      ['Καῖρα', '', 'Penult circumflex', 'αῖ', 'Herodian gives Καῖρα with long ι, and cites Apollonius on the divided form Κάϊρα. He records Κάειρα with ει as the form in usage.'],
      ['Κάϊρα', '', 'Antepenult acute', 'Κά', 'In the divided spelling Κάϊρα, the diaeresis separates α and ι. The acute falls on the first of three syllables.'],
      ['Κάειρα', 'Κάρ', 'Antepenult acute', 'Κά', 'The passage pairs Κάρ and Κάειρα. Herodian says usage has the diphthong ει by analogy with forms in -ειρα.']
    ]
  },
  {
    ending: 'Forms in -σα',
    entries: [
      ['χαρίεσσα', '', 'Antepenult acute', 'ρί', 'Derived forms in -σα of more than two syllables generally have an antepenult acute. Herodian qualifies the rule for coalesced forms from oxytones in -ης.'],
      ['τεχνῆσσα', 'τεχνήεσσα', 'Penult circumflex', 'νῆ', 'Herodian derives τεχνῆσσα from τεχνήεσσα. Compare the antepenult acute in the longer form with the penult circumflex in the shorter one.'],
      ['χερνῆσσα', 'χερνής', 'Penult circumflex', 'νῆ', 'The source pairs χερνής, with a final acute, and χερνῆσσα, with a circumflex on the next-to-last syllable.']
    ]
  },
  {
    ending: 'Other short -α forms',
    entries: [
      ['μᾶζα', '', 'Penult circumflex', 'μᾶ', 'For underived two-syllable forms pronounced with a double consonant, Herodian gives a penult circumflex when the penult is long. He singles out μᾶζα for its long α before the double consonant.'],
      ['ψῷζα', '', 'Penult circumflex', 'ψῷ', 'Herodian gives ψῷζα as another example of the penult circumflex in this group.']
    ]
  }
];

const $ = (selector) => document.querySelector(selector);
const word = $('#word');
const pattern = $('#pattern');
const forms = $('#forms');
const position = $('#position');
const explanation = $('#explanation');
const examples = new Map();
const key = (text) => text.trim().normalize('NFD').replace(/\p{M}/gu, (mark) => mark === '\u0308' ? mark : '').toLowerCase().replace(/ς/g, 'σ');

function show(entry) {
  for (const [example, button] of examples.values()) {
    button.setAttribute('aria-pressed', String(example === entry));
  }
  forms.replaceChildren();
  forms.hidden = !entry;
  position.hidden = !entry;
  if (!entry) {
    const entered = word.value.trim();
    pattern.textContent = entered ? 'Form outside these examples' : 'Choose a form';
    explanation.textContent = entered
      ? 'Try a spelling shown in the example list.'
      : 'Select an example or type its spelling to see which syllable carries the accent.';
    position.textContent = '';
    return;
  }
  const [form, base, accent, marked, note] = entry;
  const start = form.indexOf(marked);
  const highlight = document.createElement('mark');
  highlight.textContent = marked;
  if (base) forms.append(base, ' → ');
  forms.append(form.slice(0, start), highlight, form.slice(start + marked.length));
  pattern.textContent = form === 'Μελαιναί' ? 'City name' : 'Cited form';
  position.textContent = accent;
  explanation.textContent = note;
}

for (const group of groups) {
  const section = document.createElement('section');
  section.className = 'group';
  const heading = document.createElement('h2');
  heading.textContent = group.ending;
  const buttons = document.createElement('div');
  buttons.className = 'examples';
  for (const entry of group.entries) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'example';
    button.lang = 'grc';
    button.textContent = entry[0];
    button.setAttribute('aria-pressed', 'false');
    button.addEventListener('click', () => {
      word.value = entry[0];
      show(entry);
    });
    examples.set(key(entry[0]), [entry, button]);
    buttons.append(button);
  }
  section.append(heading, buttons);
  $('#examples').append(section);
}

$('#search').addEventListener('submit', (event) => {
  event.preventDefault();
  show(examples.get(key(word.value))?.[0]);
});
$('#clear').addEventListener('click', () => {
  word.value = '';
  show();
  word.focus();
});

