const entries = [
  {form: 'Ἀρτύνας', kind: 'barytone', note: 'Herodian lists Ἀρτύνας under -νας. Its acute is on the penult.'},
  {form: 'Ξένας', kind: 'barytone', note: 'Herodian lists Ξένας under -νας with a penultimate acute.'},
  {form: 'Πρατίνας', kind: 'barytone', note: 'Herodian lists Πρατίνας under -νας with a penultimate acute.'},
  {form: 'Πίνας', kind: 'barytone', note: 'Herodian lists Πίνας under -νας with a penultimate acute.'},
  {form: 'Κάνας', kind: 'barytone', note: 'Herodian lists Κάνας under -νας with a penultimate acute.'},
  {form: 'Μηνᾶς', kind: 'circumflex', note: 'Herodian identifies Μηνᾶς as a diminutive.'},
  {form: 'Ζηνᾶς', kind: 'circumflex', note: 'Herodian identifies Ζηνᾶς as a diminutive.'},
  {form: 'δακνᾶς', kind: 'circumflex', note: 'Herodian says δακνᾶς has a circumflex because it is used in mockery.'},
  {form: 'Εὐρώπας', kind: 'barytone', note: 'The penultimate acute in Εὐρώπας illustrates the -πας group.'},
  {form: 'ἅπας', kind: 'barytone', note: 'The first syllable of ἅπας retains its rough breathing and acute.'},
  {form: 'Θήρας', kind: 'barytone', note: 'Θήρας illustrates the -ρας group, with an acute before the final syllable.'},
  {form: 'Ἀθύρας', kind: 'barytone', note: 'The passage uses Ἀθύρας of a harbour and river near Byzantium and of a river in Sicily.'},
  {form: 'Τάρας', kind: 'barytone', note: 'The name of an Italian city and river. Herodian records both masculine and feminine usage.'},
  {form: 'Μητρᾶς', kind: 'circumflex', note: 'Herodian explicitly lists Μητρᾶς with a final circumflex.'},
  {form: 'Ἡρᾶς', kind: 'circumflex', note: 'Herodian explicitly lists Ἡρᾶς with a final circumflex.'},
  {form: 'βορρᾶς', kind: 'circumflex', note: 'Herodian explicitly lists βορρᾶς with a final circumflex.'},
  {form: 'τετρᾶς', kind: 'circumflex', note: 'Herodian gives this final circumflex separately from τετράς, genitive τετράδος.'},
  {form: 'τετράς', kind: 'acute', note: 'Herodian gives the genitive τετράδος and specifies that the final α of τετράς is short.'},
  {form: 'Χρύσας', kind: 'barytone', note: 'The penultimate acute in Χρύσας illustrates the -σας group.'},
  {form: 'Ἀπέσας', kind: 'barytone', note: 'Herodian cites Pindar for this mountain of Nemea.'}
];
const labels = {
  barytone: 'Accent before the final syllable',
  circumflex: 'Final circumflex',
  acute: 'Final acute'
};
const quiz = entries.filter((entry) => entry.kind !== 'acute' && entry.form !== 'τετρᾶς');
const $ = (selector) => document.querySelector(selector);
const input = $('#inp');
const output = $('#out');
const accents = /[\u0300\u0301\u0342]/g;
const key = (value) => value.trim().normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().replace(/ς/g, 'σ');
const marks = (value) => (value.normalize('NFD').match(accents) ?? []).join('');

function showLookup() {
  const value = input.value.trim();
  const matches = entries.filter((entry) => key(entry.form) === key(value));
  const explicit = matches.length > 1 && marks(value);
  const shown = explicit ? matches.filter((entry) => marks(entry.form) === explicit) : matches;
  output.replaceChildren();
  if (!shown.length) {
    const message = document.createElement('p');
    message.textContent = value
      ? 'No example in this selection matches that spelling.'
      : 'Type a Greek example to see its accent.';
    output.append(message);
    return;
  }
  for (const entry of shown) {
    const card = document.createElement('article');
    const form = document.createElement('h3');
    const accent = document.createElement('p');
    const note = document.createElement('p');
    form.lang = 'grc';
    form.textContent = entry.form;
    accent.textContent = labels[entry.kind];
    note.textContent = entry.note;
    card.append(form, accent, note);
    output.append(card);
  }
}

let index = 0;
let correct = 0;
let answered = 0;
const choices = [...document.querySelectorAll('[data-guess]')];
const reveal = $('#reveal');
const feedback = $('#feedback');
const next = $('#next');

function showQuestion() {
  $('#prompt').textContent = quiz[index].form.normalize('NFD').replace(accents, '').normalize('NFC');
  feedback.textContent = 'Choose an answer or reveal the form.';
  for (const button of [...choices, reveal]) button.disabled = false;
}

function showAnswer(guess) {
  if (reveal.disabled) return;
  const entry = quiz[index];
  let report = 'Answer';
  if (guess) {
    answered++;
    if (guess === entry.kind) correct++;
    report = guess === entry.kind ? 'Correct' : 'Try the next example';
    $('#score').textContent = `${correct} / ${answered}`;
  }
  const form = document.createElement('strong');
  form.lang = 'grc';
  form.textContent = entry.form;
  feedback.replaceChildren(report + ' · ', form, ' · ' + labels[entry.kind] + '. ' + entry.note);
  for (const button of [...choices, reveal]) button.disabled = true;
  next.focus();
}

$('#search').addEventListener('submit', (event) => {
  event.preventDefault();
  showLookup();
});
$('#clear').addEventListener('click', () => {
  input.value = '';
  showLookup();
  input.focus();
});
$('#random').addEventListener('click', () => {
  input.value = entries[Math.floor(Math.random() * entries.length)].form;
  showLookup();
});
for (const button of choices) button.addEventListener('click', () => showAnswer(button.dataset.guess));
reveal.addEventListener('click', () => showAnswer());
next.addEventListener('click', () => {
  index = (index + 1) % quiz.length;
  showQuestion();
  choices[0].focus();
});
showQuestion();

